//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.vScrenID = "ULDBNS20400.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Search = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_FEE_EXMPT_MBR_LIST";
    url += "&queryId=lds.stf.bnsfee_exmpt_mbr.select.list";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_ISUR_VAL=" + txb_isur_cd.getValue(); //txb_isur_cd txb_com_abbrv;
    url += "&{P}V_REG_YN=" + $c.stf.getObjectValue(cmb_REG_YN); // 회원여부		

    dts_List_1.DataID = encodeURI(url);
    dts_List_1.Reset();
    $c.cm.ShowWin(grd_List);
    return url;
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_isur_cd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_com_abbrv, arrPar[0].ISUR_NM);
    $c.stf.setObjectValue(txb_isur_cd, arrPar[0].ISUR_CD);
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(img_com_srch) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_com_srch);
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(panel_Top);

    //DR 및 Exa DB체크
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        //return false;

    } else {
        $c.bns.fn_BnsCheckExaDb(scwin.vScrenID, dts_ExaYn, '1');
        //return false;

    }
    scwin.fn_Search();
};
scwin.img_com_srch_onclick = function() {
    scwin.fn_ShowIsur(img_com_srch);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_List_1_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.txb_isur_cd_onblur = function() {
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.txb_isur_cd_onkeypress = function() {
    if (window.event.keyCode == 13) scwin.fn_Search();
};
scwin.btn_ToExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var title = '수수료면제거래소회원';
    var fileNm = $c.ut.cGetToday('yyyymmdd') + '_' + title;
    $c.data.downloadGridViewExcel(grd_List, title, "", "8");
};
